    redline: { tag: 'Litre bikes and one very fast GT, under one roof in Andheri.', about: 'Kabir started Redline in a two-bay garage off Link Road with three used superbikes and a dyno. Eight years later it is the shop Mumbai riders send their friends to: every bike is ridden by the team before it is listed, and nothing leaves without a fresh chain, fluids and a full tank.', hours: [['Mon–Sat', '10:30 – 20:00'], ['Sunday', '11:00 – 17:00 (test rides only)']], landmark: 'Opposite the metro pillar 112, Link Road', services: ['Home test rides across the western suburbs', 'Track-day prep and suspension setup', 'Part-exchange on superbikes and cars', 'Same-week RC transfer'], reply: '9 min', sold: 46, img: 'b-rosso',
      quotes: [['Rohit P.', 'Bought a 1000cc superbike', 5, 'They pointed out a tyre that needed replacing before I even asked, and swapped it before delivery. The report matched the bike to the letter.'], ['Sneha K.', 'Sold her café racer', 5, 'Inspection at my building on a Saturday, three dealer bids by Monday. Redline paid the top one the same day.'], ['Aamir S.', 'Test rode three bikes', 4, 'Sunday test-ride slots go fast. Book early. Kabir knows every bike on the floor by heart.']] },
    torque: { tag: 'Indiranagar’s calmest showroom for bikes and enthusiast cars.', about: 'Torque & Co. is two floors of bikes and cars on 100 Feet Road, run by Ananya and a team of four ex-service advisers. They specialise in manual enthusiast cars and middleweight bikes, and they will talk you out of buying the wrong one.', hours: [['Tue–Sun', '10:00 – 19:30'], ['Monday', 'Closed']], landmark: 'Above the bakery on 100 Feet Road, Indiranagar', services: ['Weekend test drives on the Nandi Hills loop', 'Finance from three partner banks', 'Ceramic coating and PPF in-house', 'Free 1,000 km check after delivery'], reply: '14 min', sold: 61, img: 'c-azure',
      quotes: [['Deepa M.', 'Bought a performance sedan', 5, 'A manual sedan with a proper diff, exactly as described. They even had the original window sticker.'], ['Varun T.', 'Bought a 650 café racer', 5, 'My first big bike. They spent an hour on the controls before letting me ride it home.'], ['Kiran B.', 'Part-exchanged a hatchback', 4, 'Fair price for my old car and no haggling games. Paperwork took a week longer than promised.']] },
    northgate: { tag: 'Gurugram’s grown-up luxury floor: SUVs, GTs and quiet confidence.', about: 'Northgate Motors has sold pre-owned luxury cars on Golf Course Road since 2011. Vikram’s team runs a 40-point pre-check before Revv’s own 150, so cars that reach the floor rarely carry more than one advisory.', hours: [['Mon–Sat', '10:00 – 20:00'], ['Sunday', 'By appointment']], landmark: 'Next to the Sector 29 food court, Gurugram', services: ['Chauffeured test drives from your office', 'Extended warranty transfers', 'Insurance renewal on delivery', 'Pick-up and drop for the first service'], reply: '11 min', sold: 38, img: 'c-coupe',
      quotes: [['Ankit G.', 'Bought an SUV coupé', 5, 'The extended warranty moved to my name before delivery. The car was detailed like it had just left the factory.'], ['Mehak S.', 'Bought a naked triple', 4, 'Not their usual stock, but they knew the bike well and the price was right.'], ['Rahul D.', 'Booked a test drive', 5, 'They brought the car to my office in Cyber City and waited while I drove it home and back.']] },
